package com.student.controller;
import com.student.dao.AdminDAO; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class SettingsServlet extends HttpServlet{private final AdminDAO dao=new AdminDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}try{req.setAttribute("adminName",dao.getName());req.setAttribute("username",dao.getUsername());req.getRequestDispatcher("/settings.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}try{String name=req.getParameter("adminName"),user=req.getParameter("username"),newPass=req.getParameter("password"),confirm=req.getParameter("confirmPassword");if(name==null||name.isBlank()||user==null||user.isBlank())throw new IllegalArgumentException();String pass=dao.getPassword();if(newPass!=null&&!newPass.isBlank()){if(!newPass.equals(confirm))throw new IllegalArgumentException();pass=newPass;}dao.update(name.trim(),user.trim(),pass);HttpSession s=req.getSession();s.setAttribute("adminName",name.trim());s.setAttribute("adminUsername",user.trim());resp.sendRedirect("settings?success=1");}catch(Exception e){req.setAttribute("error","Could not update settings. Check the details and make sure the new passwords match.");try{req.setAttribute("adminName",dao.getName());req.setAttribute("username",dao.getUsername());}catch(Exception ignored){}req.getRequestDispatcher("/settings.jsp").forward(req,resp);}}}
